SELECT task_no AS taskNo, message_id AS messageId, correlation_id AS correlationId, dead_letter_routing_key AS deadLetterRoutingKey, target_system AS targetSystem, replay_exchange AS replayExchange, replay_routing_key AS replayRoutingKey, task_status AS taskStatus, task_status_type AS taskStatusType, resolution_note AS resolutionNote, payload_snapshot AS payloadSnapshot, header_snapshot AS headerSnapshot, replay_count AS replayCount, DATE_FORMAT(last_replay_at, '%Y-%m-%d %H:%i:%s') AS lastReplayAt, operator, DATE_FORMAT(resolved_at, '%Y-%m-%d %H:%i:%s') AS resolvedAt, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt FROM t_payment_dead_letter_task
task_status = #{query.taskStatus}
AND target_system = #{query.targetSystem}
AND message_id LIKE CONCAT('%', #{query.messageId}, '%')
ORDER BY created_at DESC, id DESC LIMIT #{query.limit} OFFSET #{query.offset}

SELECT COUNT(1)
FROM t_payment_dead_letter_task


        task_status = #{query.taskStatus}


        AND target_system = #{query.targetSystem}


        AND message_id LIKE CONCAT('%', #{query.messageId}, '%')
